const response = $input.item.json;
const items = response.items || [];
const config = $('Configuración').item.json;

return items.map(post => ({
  json: {
    postId: post.id,
    blogId: config.BLOG_ID_ANIMALES,
    titulo: post.title,
    contenido: post.content,
    url: post.url,
    nicho: 'animales',
    productos: config.PRODUCTOS_ANIMALES,
    yaTieneMonetizacion: (post.content || '').includes('go.hotmart.com')
  }
}));

const response = $input.item.json;
const items = response.items || [];
const config = $('Configuración').item.json;

return items.map(post => ({
  json: {
    postId: post.id,
    blogId: config.BLOG_ID_LEYES,
    titulo: post.title,
    contenido: post.content,
    url: post.url,
    nicho: 'leyes',
    productos: [],
    yaTieneMonetizacion: (post.content || '').includes('go.hotmart.com')
  }
}));

const post = $input.item.json;
const titulo = (post.titulo || '').toLowerCase();
const contenido = (post.contenido || '').toLowerCase();

// Seleccionar el producto más relevante por keywords
let productoSeleccionado = post.productos[0]; // default: primer producto
let mejorScore = 0;

for (const producto of post.productos) {
  const score = producto.keywords.filter(kw => titulo.includes(kw) || contenido.includes(kw)).length;
  if (score > mejorScore) {
    mejorScore = score;
    productoSeleccionado = producto;
  }
}

// Generar el banner con imagen real del producto
const banner = `
<!-- BANNER MONETIZACIÓN HOTMART -->
<div style="background:#f0faf4;border-radius:14px;padding:0;margin:40px 0;overflow:hidden;box-shadow:0 4px 16px rgba(0,0,0,.12);font-family:Arial,sans-serif;max-width:700px;border:1px solid #c3e6d0">
  <div style="display:flex;align-items:stretch;flex-wrap:wrap">
    <img src="${productoSeleccionado.imagen}" alt="${productoSeleccionado.nombre}" style="width:150px;height:auto;object-fit:cover;flex-shrink:0">
    <div style="flex:1;min-width:180px;padding:20px;display:flex;flex-direction:column;justify-content:center">
      <p style="color:#1a7a4a;font-size:10px;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;margin:0 0 5px">${productoSeleccionado.tipo} recomendado 🐾</p>
      <h3 style="color:#1a1a1a;font-size:17px;font-weight:800;margin:0 0 8px;line-height:1.3">${productoSeleccionado.nombre}</h3>
      <p style="color:#555;font-size:13px;margin:0 0 14px;line-height:1.5">Aprende todo lo que necesitas saber paso a paso.</p>
      <a href="${productoSeleccionado.link}" target="_blank" rel="noopener sponsored"
         style="display:inline-block;background:#1a7a4a;color:#fff;font-weight:800;font-size:13px;padding:10px 20px;border-radius:8px;text-decoration:none;align-self:flex-start">
        Ver ahora →
      </a>
    </div>
  </div>
  <p style="color:#aaa;font-size:10px;text-align:right;margin:0;padding:6px 14px">*Enlace de afiliado</p>
</div>
<!-- FIN BANNER -->`;

return [{ json: { ...post, contenidoActualizado: post.contenido + banner, productoUsado: productoSeleccionado.nombre } }];

const animales = $('Actualizar en Blogger - Animales').all();
const leyes    = $('Actualizar en Blogger - Leyes').all();
console.log(`✅ ${animales.length + leyes.length} posts monetizados`);
return [{ json: {
  timestamp: new Date().toISOString(),
  total: animales.length + leyes.length,
  animales: animales.length,
  leyes: leyes.length
}}];
